package com.payflow.transaction; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import java.math.BigDecimal; import java.time.Instant; import java.util.Map;
@Component public class KafkaConsumer { final TransactionRepo repo; public KafkaConsumer(TransactionRepo r){repo=r;} @KafkaListener(topics="payment-events",groupId="transaction-service") public void consume(Map<String,Object> e){if(repo.findAll().stream().anyMatch(x->x.transactionId.equals(e.get("transactionId"))))return;TransactionRecord t=new TransactionRecord();t.transactionId=e.get("transactionId").toString();t.senderAccountId=Long.valueOf(e.get("senderAccountId").toString());t.merchantId=Long.valueOf(e.get("merchantId").toString());t.amount=new BigDecimal(e.get("amount").toString());t.status=e.get("status").toString();t.createdAt=Instant.now();repo.save(t);}}
